package com.threatstream.detection;
import java.time.Instant; import java.util.*; import org.springframework.stereotype.Component;
@Component class BruteForceRule implements DetectionRule { private final DetectionProperties p; private final AlertFactory f; private final Map<String,Deque<Instant>> state=new HashMap<>(); private final Set<String> armed=new HashSet<>(); BruteForceRule(DetectionProperties p,AlertFactory f){this.p=p;this.f=f;}
 public synchronized Optional<SecurityAlert> evaluate(AuthEvent e){ if(!"FAILURE".equals(e.outcome()))return Optional.empty(); Deque<Instant> q=state.computeIfAbsent(e.sourceIp(),x->new ArrayDeque<>()); Instant cut=e.timestamp().minus(p.bruteForce().window()); while(!q.isEmpty()&&q.peek().isBefore(cut))q.remove(); if(q.isEmpty())armed.remove(e.sourceIp()); q.add(e.timestamp()); return q.size()>=p.bruteForce().threshold()&&armed.add(e.sourceIp())?Optional.of(f.create("AUTH_BRUTE_FORCE","BRUTE_FORCE","HIGH",e,q.size(),q.peek())):Optional.empty(); } }
